from django.test import TestCase

# Configure Django settings
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'django.contrib.contenttypes',
            'django.contrib.auth',
        ],
    )
    django.setup()

class NamedCategory(models.Model):
    name = models.CharField(max_length=10)
    class Meta:
        app_label = 'reproduction'

class Tag(models.Model):
    category = models.ForeignKey(NamedCategory, models.SET_NULL, null=True)
    class Meta:
        app_label = 'reproduction'

class Item(models.Model):
    tags = models.ManyToManyField(Tag)
    class Meta:
        app_label = 'reproduction'

class Number(models.Model):
    num = models.IntegerField()
    class Meta:
        app_label = 'reproduction'

# To avoid having to run migrations, we can use schema_editor to create tables.
from django.db import connection

def setup_db():
    with connection.schema_editor() as schema_editor:
        schema_editor.create_model(NamedCategory)
        schema_editor.create_model(Tag)
        schema_editor.create_model(Item)
        schema_editor.create_model(Number)

setup_db()

def test_exists_exclude():
    print("Testing filter()...")
    try:
        qs = Number.objects.annotate(
            foo=Exists(
                Item.objects.filter(tags__category_id=OuterRef('pk'))
            )
        ).filter(foo=True)
        print("filter() works")
    except Exception as e:
        print(f"filter() failed: {e}")

    print("\nTesting exclude()...")
    try:
        qs = Number.objects.annotate(
            foo=Exists(
                Item.objects.exclude(tags__category_id=OuterRef('pk'))
            )
        ).filter(foo=True)
        print(qs)
        print("exclude() works")
    except Exception as e:
        print(f"exclude() failed: {e}")
        import traceback
        traceback.print_exc()

    print("\nTesting filter(~Q())...")
    try:
        qs = Number.objects.annotate(
            foo=Exists(
                Item.objects.filter(~Q(tags__category_id=OuterRef('pk')))
            )
        ).filter(foo=True)
        print(qs)
        print("filter(~Q()) works")
    except Exception as e:
        print(f"filter(~Q()) failed: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_exists_exclude()
