    name = 'repro'

django.apps.apps.add_app_config(ReproConfig())
django.setup()

class Foo(models.Model):
    name = models.CharField(max_length=300, unique=True)
    class Meta:
        app_label = 'repro'
        constraints = [
            UniqueConstraint(
                Lower("name").desc(), name="unique_lower_name"
            )
        ]

# Create the table
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(Foo)

def test_unique_constraint_ordered_expression():
    try:
        # First instance
        foo1 = Foo(name="foo1")
        foo1.full_clean()
        foo1.save()
        print("Successfully saved foo1")

        # Second instance with same name (should raise ValidationError)
        foo2 = Foo(name="FOO1")
        try:
            foo2.full_clean()
            print("Error: full_clean should have raised ValidationError for foo2")
        except ValidationError as e:
            print(f"Caught expected ValidationError for foo2: {e}")

    except Exception as e:
        print(f"Caught unexpected exception: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_unique_constraint_ordered_expression()
