    field = JSONField()
    value = {'name': '中国'}
    prepared = field.prepare_value(value)

    # Check if it's unicode by checking if it's not escaped
    if '\\u' not in prepared and '中国' in prepared:
        print("SUCCESS: Unicode characters are NOT escaped.")
    else:
        print("FAILURE: Unicode characters are still escaped or missing.")

if __name__ == "__main__":
    test_unicode_display()
